import 'package:cloud_firestore/cloud_firestore.dart';

enum UserRole { student, advisor, admin }
UserRole userRoleFromString(String? value) => UserRole.values.firstWhere((role) => role.name == value, orElse: () => UserRole.student);
class UserModel { const UserModel({required this.id, required this.name, required this.email, required this.role, required this.createdAt, this.phone, this.photoUrl, this.isActive = true}); final String id, name, email; final UserRole role; final String? phone, photoUrl; final bool isActive; final DateTime createdAt;
factory UserModel.fromMap(String id, Map<String,dynamic> map) => UserModel(id:id,name:map['name'] as String? ?? '',email:map['email'] as String? ?? '',role:userRoleFromString(map['role'] as String?),phone:map['phone'] as String?,photoUrl:map['photoUrl'] as String?,isActive:map['isActive'] as bool? ?? true,createdAt:(map['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now());
Map<String,dynamic> toMap() => {'name':name,'email':email,'role':role.name,'phone':phone,'photoUrl':photoUrl,'isActive':isActive,'createdAt':Timestamp.fromDate(createdAt),'updatedAt':FieldValue.serverTimestamp()};
UserModel copyWith({String? name,String? phone,String? photoUrl,bool? isActive}) => UserModel(id:id,name:name??this.name,email:email,role:role,phone:phone??this.phone,photoUrl:photoUrl??this.photoUrl,isActive:isActive??this.isActive,createdAt:createdAt); }
class StudentProfile { const StudentProfile({required this.userId,this.university='',this.college='',this.department='',this.academicLevel='',this.gpa,this.skillIds=const [],this.interests=const []}); final String userId,university,college,department,academicLevel; final double? gpa; final List<String> skillIds,interests;
factory StudentProfile.fromMap(String id,Map<String,dynamic> map)=>StudentProfile(userId:id,university:map['university'] as String? ?? '',college:map['college'] as String? ?? '',department:map['department'] as String? ?? '',academicLevel:map['academicLevel'] as String? ?? '',gpa:(map['gpa'] as num?)?.toDouble(),skillIds:List<String>.from(map['skillIds']??const []),interests:List<String>.from(map['interests']??const []));
Map<String,dynamic> toMap()=>{'university':university,'college':college,'department':department,'academicLevel':academicLevel,'gpa':gpa,'skillIds':skillIds,'interests':interests,'updatedAt':FieldValue.serverTimestamp()}; double get completion=>[university,college,department,academicLevel].where((item)=>item.isNotEmpty).length/4; }
